return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : ((n == 0) || (n == 1)) ? 0 : 2);','language'=>'fr_FR','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-29T17:24:54+00:00','po-revision-date'=>'2026-09-29T17:24:54+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A complete help desk and AI assistant that runs on your own WordPress: an AI that answers from your own pages with links, live chat, and support tickets in wp-admin, on a submit-a-ticket page and in the WooCommerce account area. Under 10 KB on the page and no requests at all until a visitor opens it.'=>'Un service d\'assistance complet et un assistant IA qui fonctionnent sur votre propre WordPress : une IA qui répond à partir de vos propres pages avec des liens, un chat en direct et des tickets de support dans wp-admin, sur une page de soumission de ticket et dans l\'espace client WooCommerce. Moins de 10 Ko sur la page et aucune requête tant qu\'un visiteur ne l\'ouvre pas.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Inbox'=>'Boîte de réception','Tickets'=>'Tickets','Assistant'=>'Assistant','Settings'=>'Paramètres','Setup'=>'Configuration','Zinn® Chat could not create its database tables:'=>'Zinn® Chat n\'a pas pu créer ses tables de base de données :','The AI assistant could not answer a visitor:'=>'L\'assistant IA n\'a pas pu répondre à un visiteur :','Fix it'=>'Corriger','Loading…'=>'Chargement…','This screen needs JavaScript.'=>'Cet écran nécessite JavaScript.','Chat'=>'Chat','AI assistant'=>'Assistant IA','Tickets and email'=>'Tickets et e-mails','Site index'=>'Index du site','Privacy and spam'=>'Confidentialité et spam','Connect to Zinn Digital®'=>'Se connecter à Zinn Digital®','Show the chat on the site'=>'Afficher le chat sur le site','Nothing appears on the site, and nothing is loaded, until this is ticked.'=>'Rien n\'apparaît sur le site et rien ne se charge tant que cette case n\'est pas cochée.','Chat title'=>'Titre de la discussion','Greeting'=>'Message d\'accueil','The first thing a visitor sees.'=>'La première chose qu\'un visiteur voit.','Greeting when nobody can answer'=>'Message d\'accueil lorsqu\'aucune réponse n\'est possible','Colour'=>'Couleur','Text colour on the colour'=>'Couleur du texte sur la couleur','Position'=>'Position','Bottom, end side (right in left-to-right languages)'=>'Bas, côté de fin (droite dans les langues de gauche à droite)','Bottom, start side'=>'Bas, début','Offer "Talk to a person"'=>'Offrir l\'option « Parler à une personne »','Shown while somebody has the Inbox open and is not set to away.'=>'Affiché lorsqu\'un utilisateur a la Boîte de réception ouverte et n\'est pas défini comme absent.','Hide the chat from your support team while they are signed in'=>'Masquer le chat pour votre équipe de support lorsqu\'elle est connectée','Show "Powered by Zinn® Chat" under the chat'=>'Afficher « Propulsé par Zinn® Chat » sous le chat','Optional. Off unless you turn it on.'=>'Optionnel. Désactivé sauf si vous l\'activez.','Let the AI assistant answer visitors'=>'Permettez à l\'assistant IA de répondre aux visiteurs','Assistant name'=>'Nom de l\'assistant','Extra instructions for the assistant'=>'Instructions supplémentaires pour l\'assistant','For example: "Always mention our 30-day returns." They cannot override the safety rules.'=>'Par exemple : « Mentionnez toujours notre garantie de retour de 30 jours. » Ils ne peuvent pas contourner les règles de sécurité.','Answer language'=>'Langue des réponses','"auto" answers in the visitor\'s own language; or a locale such as en_GB or de_DE to always answer in one language.'=>'"auto" répond dans la propre langue du visiteur ; ou un code de localisation tel que en_GB ou de_DE pour répondre toujours dans une seule langue.','Minimum relevance'=>'Pertinence minimale','Passages scoring below this (0 to 0.95) are not used, and the assistant says it does not know. Check scores in the test console.'=>'Les passages ayant un score inférieur à celui-ci (0 à 0,95) ne sont pas utilisés, et l\'assistant indique qu\'il ne sait pas. Vérifiez les scores dans la console de test.','Offer a person after this many unanswered questions'=>'Proposer à une personne après ce nombre de questions sans réponse','Longest answer (tokens)'=>'Réponse la plus longue (jetons)','Accept support tickets'=>'Accepter les tickets de support','Support page'=>'Page d\'assistance','The page with the [zinn_chat_support] shortcode or the Support page block. Ticket links in emails open this page.'=>'La page contenant le code court [zinn_chat_support] ou le bloc de page de support. Les liens vers les tickets dans les e-mails ouvrent cette page.','Send team alerts to'=>'Envoyer les alertes d\'équipe à','One or more email addresses, separated by commas. Empty: the site admin email.'=>'Une ou plusieurs adresses e-mail, séparées par des virgules. Vide : l\'e-mail de l\'administrateur du site.','Sender name on emails'=>'Nom d\'expéditeur des e-mails','Email the team when a visitor waits for a person longer than (minutes)'=>'Envoyer un e-mail à l\'équipe lorsqu\'un visiteur attend une personne plus de (minutes)','Private ticket links work for (days after the last message)'=>'Les liens de tickets privés fonctionnent pendant (jours après le dernier message)','After that the page offers to email a new link.'=>'Ensuite, la page propose d\'envoyer un nouveau lien par e-mail.','Add a Support tab to the WooCommerce account area'=>'Ajouter un onglet Support à l\'espace client WooCommerce','Let the assistant tell signed-in customers about their own orders'=>'Permettre à l\'assistant d\'informer les clients connectés de leurs propres commandes','Answers "where is my order?" from the order status and tracking.'=>'Répond au « où est ma commande ? » depuis le statut de la commande et le suivi.','Content the assistant reads'=>'Contenu lu par l\'assistant','None ticked means every public type.'=>'Aucune sélection signifie tous les types publics.','WooCommerce products, prices, stock, shipping and payment methods'=>'Produits, prix, stock, modes de livraison et de paiement WooCommerce','Forums (bbPress, BuddyBoss, wpForo)'=>'Forums (bbPress, BuddyBoss, wpForo)','Read pages as visitors see them when a page builder\'s content cannot be read directly'=>'Lire les pages telles que les visiteurs les voient lorsque le contenu d\'un constructeur de page ne peut pas être lu directement','Fetches the page from your own site in the background.'=>'Récupère la page de votre propre site en arrière-plan.','Never read these posts or pages (IDs)'=>'Ne jamais lire ces publications ou pages (IDs)','Comma-separated.'=>'Séparés par des virgules.','Ask visitors to agree before a chat or ticket'=>'Demander aux visiteurs de donner leur accord avant un chat ou un ticket','Agreement text'=>'Texte de l\'accord','Privacy policy link'=>'Lien vers la politique de confidentialité','Empty: the site\'s privacy policy page.'=>'Vide : la page de politique de confidentialité du site.','Delete finished chats and tickets after (days)'=>'Supprimer les discussions et les tickets terminés après (jours)','0 keeps them.'=>'0 les conserve.','Store visitors\' IP addresses'=>'Enregistrer les adresses IP des visiteurs','Off: only a coded form is kept, enough for spam limits.'=>'Désactivé : seule une forme codée est conservée, suffisante pour les limites de spam.','Messages per visitor per hour'=>'Messages par visiteur et par heure','Chats per visitor per day'=>'Discussions par visiteur et par jour','Tickets per visitor per day'=>'Tickets par visiteur et par jour','Longest chat message (characters)'=>'Message de chat le plus long (caractères)','Block list'=>'Liste de blocage','One per line: an IP address, an email address, @domain.com, or a word.'=>'Un par ligne : une adresse IP, une adresse e-mail, @domain.com ou un mot.','Where chats are answered'=>'Où les discussions reçoivent une réponse','"This site" keeps everything in this site\'s database and uses your own AI key. "Zinn Digital®" uses the hosted inbox in the Zinn® app (for Zinn® hosting customers).'=>'« Ce site » conserve tout dans la base de données de ce site et utilise votre propre clé d\'IA. « Zinn Digital® » utilise la boîte de réception hébergée dans l\'application Zinn® (pour les clients de l\'hébergement Zinn®).','This site (recommended)'=>'Ce site (recommandé)','Zinn Digital® app'=>'Application Zinn Digital®','Zinn® widget key'=>'clé de widget Zinn®','From the Zinn® app: Live chat, then your widget. Starts with zc_.'=>'Depuis l\'application Zinn® : Clavardage en direct, puis votre widget. Commence par zc_.','Zinn® Chat settings'=>'Paramètres de Zinn® Chat','Settings saved.'=>'Paramètres enregistrés.','The assistant uses your own AI key.'=>'L\'assistant utilise votre propre clé d\'IA.','AI providers and models'=>'Fournisseurs et modèles d\'IA','— None —'=>'— Aucun —','Saved — leave empty to keep'=>'Enregistré — laisser vide pour conserver','Remove the saved key'=>'Supprimer la clé enregistrée','You are not allowed to change these settings.'=>'Vous n\'êtes pas autorisé à modifier ces paramètres.','Turn the chat on'=>'Activer le chat','The chat is showing on your site.'=>'Le chat s\'affiche sur votre site.','Nothing is shown or loaded on your site until you turn it on.'=>'Rien ne s\'affiche ou ne se charge sur votre site tant que vous ne l\'activez pas.','Turn off'=>'Désactiver','Turn on'=>'Activer','Connect your AI provider'=>'Connecter votre fournisseur d\'IA','Connected. Site search uses %1$s (%2$s).'=>'Connecté. La recherche sur le site utilise %1$s (%2$s).','Connected. Your provider cannot build a meaning-based index, so the assistant uses keyword search. Add a Google Gemini, OpenAI, Mistral or OpenRouter key for better answers.'=>'Connecté. Votre fournisseur ne pouvant pas créer d\'index sémantique, l\'assistant utilise une recherche par mots-clés. Ajoutez une clé Google Gemini, OpenAI, Mistral ou OpenRouter pour obtenir de meilleures réponses.','Add a key for Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter or any OpenAI-compatible service. The newest model is chosen for you; you can change it.'=>'Ajoutez une clé pour Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter ou tout autre service compatible avec OpenAI. Le modèle le plus récent est sélectionné automatiquement, mais vous pouvez le modifier.','AI providers'=>'Fournisseurs d\'IA','Let the assistant read your site'=>'Permettez à l\'assistant de lire votre site','%1$d pages read, %2$d waiting, %3$d passages. New and edited content is picked up automatically.'=>'%1$d pages lues, %2$d en attente, %3$d passages. Le contenu nouveau et modifié est récupéré automatiquement.','Read the whole site now'=>'Lisez tout le site maintenant','Create your support page'=>'Créer votre page de support','Visitors submit tickets there, and ticket emails link to it.'=>'Les visiteurs y soumettent des tickets, et les e-mails de tickets y renvoient.','A page with the ticket form, where customers also follow their requests.'=>'Une page contenant le formulaire de ticket, où les clients suivent également leurs demandes.','View'=>'Afficher','Create the support page'=>'Créer la page de support','Add "Submit a ticket" and "Chat with us" to a menu'=>'Ajouter "Soumettre un ticket" et "Discuter avec nous" à un menu','Appearance, Menus: use the Zinn® Chat box. Or add the Zinn® Chat blocks to any page, in any page builder.'=>'Apparence, Menus : utilisez la boîte Zinn® Chat. Ou ajoutez les blocs Zinn® Chat à n\'importe quelle page, dans n\'importe quel constructeur de pages.','Menus'=>'Menus','WooCommerce account area'=>'Espace client WooCommerce','Customers see their tickets under Support in My Account, and the assistant can tell them where their order is.'=>'Les clients voient leurs tickets sous Support dans Mon compte, et l\'assistant peut leur indiquer où se trouve leur commande.','Test the assistant'=>'Tester l\'assistant','Ask it questions and see exactly which pages it answered from, including out-of-date ones.'=>'Posez-lui des questions et voyez exactement quelles pages ont servi à y répondre, y compris les plus anciennes.','Open the test console'=>'Ouvrir la console de test','Answer live chats'=>'Répondre aux chats en direct','Visitors can ask for a person while you have the Inbox open. It works on a phone too.'=>'Les visiteurs peuvent demander à parler à une personne lorsque vous avez la boîte de réception ouverte. Cela fonctionne également sur un téléphone.','Open the Inbox'=>'Ouvrir la boîte de réception','Set up Zinn® Chat'=>'Configurer Zinn® Chat','This site is connected to the Zinn Digital® app: chats are answered there. To run the help desk on this site instead, choose "This site" under Settings, Connect to Zinn Digital®.'=>'Ce site est connecté à l\'application Zinn Digital® : les chats y reçoivent des réponses. Pour utiliser plutôt le service d\'assistance sur ce site, choisissez « Ce site » sous Paramètres, Connecter à Zinn Digital®.','You are not allowed to do that.'=>'Vous n\'êtes pas autorisé à faire cela.','Unlimited agents, with a Support agent role that sees only chats and tickets'=>'Agents illimités, avec un rôle d\'agent de support qui ne voit que les discussions et les tickets','Reply to tickets by email'=>'Répondre aux tickets par e-mail','Knowledge base: articles, categories, search, and a KB section in the chat'=>'Base de connaissances : articles, catégories, recherche et section de la BC dans le chat','Saved replies, business hours, priorities and SLAs'=>'Réponses enregistrées, heures d\'ouverture, priorités et SLA','Suggested replies, thread summaries and auto-tagging by AI'=>'Réponses suggérées, résumés de fils de discussion et étiquetage automatique par IA','Knowledge-gap report: the questions your site could not answer'=>'Rapport d\'écart de connaissances : les questions auxquelles votre site n\'a pas pu répondre','Push notifications and an installable agent app for your phone'=>'Notifications push et application agent installable pour votre téléphone','Proactive messages, reports, webhooks, Slack and Telegram alerts'=>'Messages proactifs, rapports, webhooks, alertes Slack et Telegram','Zinn® Chat Pro'=>'Zinn® Chat Pro','From $%1$d a month or $%2$d a year for one site.'=>'À partir de $%1$d par mois ou $%2$d par an pour un site.','Try Pro free for 14 days'=>'Essayez Pro gratuitement pendant 14 jours','See plans'=>'Voir les offres','No card needed for the trial.'=>'Aucune carte n\'est requise pour l\'essai.','The makers of ChatGPT. A good all-rounder.'=>'Les créateurs de ChatGPT. Un bon outil polyvalent.','The makers of Claude. Strong at writing and careful reasoning.'=>'Les créateurs de Claude. Performant en rédaction et doté d\'un raisonnement rigoureux.','Google\'s Gemini models. Fast and inexpensive.'=>'Les modèles Gemini de Google. Rapides et économiques.','A European AI company with fast, inexpensive models.'=>'Une entreprise européenne d\'IA proposant des modèles rapides et économiques.','Low-cost models that are good at writing and code.'=>'Des modèles économiques performants en écriture et en programmation.','One key for models from many different providers.'=>'Une clé unique pour les modèles de nombreux fournisseurs différents.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Tout service fonctionnant comme l\'API de OpenAI, y compris un modèle exécuté sur votre propre ordinateur ou serveur.','General (used when nothing more specific is set)'=>'Général (utilisé lorsqu\'aucun paramètre plus spécifique n\'est défini)','Writing and rewriting'=>'Écriture et réécriture','Translation'=>'Traduction','Code and CSS'=>'Code et CSS','Sorry, you are not allowed to access this page.'=>'Désolé, vous n\'êtes pas autorisé à accéder à cette page.','These settings are shared by every plugin that uses them: %s.'=>'Ces paramètres sont partagés par tous les plugins qui les utilisent : %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vos clés sont chiffrées dans la base de données de ce site et ne sont jamais envoyées qu\'au fournisseur que vous avez choisi — jamais à nous.','Step 1 of 2: choose an AI provider'=>'Étape 1 sur 2 : choisissez un fournisseur d\'IA','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Vous fournissez votre propre clé, vous payez donc directement le fournisseur en fonction de votre utilisation. Vous hésitez ? N\'importe laquelle de ces options convient ; vous pourrez en ajouter d\'autres plus tard.','Next'=>'Suivant','Step 2 of 2: connect %s'=>'Étape 2 sur 2 : connecter %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Entrez l\'adresse de votre service compatible avec OpenAI, se terminant par /v1. Une clé n\'est nécessaire que si le service en demande une.','Open %s and sign in (or create a free account).'=>'Ouvrez %s et connectez-vous (ou créez un compte gratuit).','the %s API keys page'=>'la page des clés API %s','Create a new key and copy it.'=>'Créez une nouvelle clé et copiez-la.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Collez-le ci-dessous et appuyez sur « Enregistrer et tester ». Nous envoyons une seule et unique requête pour vérifier que tout fonctionne.','Most providers need a little credit on the account before a key works: %s.'=>'La plupart des fournisseurs demandent un petit crédit sur le compte avant qu\'une clé ne fonctionne : %s.','add credit'=>'ajouter du crédit','← Choose a different provider'=>'← Choisir un autre fournisseur','Address'=>'Adresse','Saved key ends in …%s — paste a new one to replace it'=>'La clé enregistrée se termine par …%s — collez-en une nouvelle pour la remplacer','Key (optional)'=>'Clé (facultative)','API key'=>'Clé API','Save and test'=>'Enregistrer et tester','Providers'=>'Fournisseurs','Provider'=>'Fournisseur','Status'=>'État','Key'=>'Clé','Get a key'=>'Obtenir une clé','Test'=>'Test','Remove'=>'Supprimer','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Enregistré par une version plus récente de l\'extension : mettez cette extension à jour ou saisissez à nouveau la clé.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'La clé enregistrée ne peut plus être ouverte (les clés de sécurité du site ont changé). Veuillez la saisir à nouveau.','Not connected'=>'Non connecté','Connected — last test passed %s'=>'Connecté — dernier test réussi le %s','Last test failed: %s'=>'Dernier test échoué : %s','Connected — not tested yet'=>'Connecté — pas encore testé','Which model to use'=>'Quel modèle utiliser','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ indique notre recommandation pour cette tâche. La liste comprend tous les modèles que votre clé peut utiliser, actualisés en direct auprès du fournisseur.','— Recommended for the provider —'=>'— Recommandé par le fournisseur —','Save models'=>'Enregistrer les modèles','Refresh the model lists from the providers'=>'Actualiser les listes de modèles auprès des fournisseurs','Images'=>'Images','Connect OpenAI or Google Gemini to make images.'=>'Connectez OpenAI ou Google Gemini pour créer des images.','— The newest image model of the first connected provider —'=>'— Le tout dernier modèle d\'image du premier fournisseur connecté —','Site search (embeddings)'=>'Recherche sur le site (embeddings)','Connect Google Gemini, OpenAI, Mistral or OpenRouter to build a search index of your site.'=>'Connectez Google Gemini, OpenAI, Mistral ou OpenRouter pour créer un index de recherche de votre site.','— The newest embedding model of the first connected provider —'=>'— Le tout dernier modèle d\'incorporation du premier fournisseur connecté —','Changing this rebuilds the search index of every plugin that uses it.'=>'La modification de ce paramètre régénère l\'index de recherche de chaque plugin qui l\'utilise.','best quality'=>'meilleure qualité','lowest cost'=>'coût le plus bas','fastest'=>'le plus rapide','Add a model yourself'=>'Ajouter un modèle vous-même','A model came out today? Paste its exact name to use it straight away.'=>'Un nouveau modèle est sorti aujourd\'hui ? Collez son nom exact pour l\'utiliser immédiatement.','Model name'=>'Nom du modèle','Add model'=>'Ajouter un modèle','Recommended models list'=>'Liste des modèles recommandés','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'La liste des modèles recommandés n\'a pas pu être vérifiée, aucune recommandation n\'est donc affichée. Réinstallez le module ou activez les mises à jour quotidiennes ci-dessous.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'La liste utilisée a été publiée le %s. Chaque mise à jour de plugin en apporte une nouvelle.','Also check Zinn Digital® once a day for an updated list.'=>'Consultez également Zinn Digital® une fois par jour pour obtenir une liste mise à jour.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Seule une simple requête de téléchargement est envoyée : aucune clé, aucune adresse de site, rien concernant votre contenu. La liste est signée, et toute liste dont la vérification de la signature échoue est ignorée.','Last checked %1$s: %2$s.'=>'Dernière vérification %1$s : %2$s.','Save, and check now if turned on'=>'Enregistrer et vérifier maintenant si l\'option est activée','a newer list was installed'=>'une liste plus récente a été installée','already up to date'=>'déjà à jour','the download failed the signature check and was ignored'=>'le téléchargement a échoué à la vérification de la signature et a été ignoré','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® est injoignable ; la liste actuelle reste en vigueur','turned off'=>'désactivé','Open'=>'Ouvrir','Check their status page'=>'Consulter leur page d\'état','Open your billing page'=>'Ouvrir votre page de facturation','Open your API keys page'=>'Ouvrez votre page de clés API','Open the AI settings'=>'Ouvrir les paramètres de l\'IA','Sorry, you are not allowed to do that.'=>'Désolé, vous n\'avez pas l\'autorisation de faire cela.','Unknown provider.'=>'Fournisseur inconnu.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Entrez l\'adresse de votre service, par exemple http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Cela ne ressemble pas à une clé API. Copiez-la à nouveau, sans espaces.','Paste your API key first.'=>'Veuillez d\'abord coller votre clé API.','Key removed.'=>'Clé supprimée.','Models saved.'=>'Modèles enregistrés.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Entrez le nom exact du modèle, tel qu\'il est écrit dans la documentation du fournisseur, par exemple.','Added %s. Choose it under "Which model to use".'=>'%s ajouté. Choisissez-le sous "Quel modèle utiliser".','Model removed.'=>'Modèle supprimé.','Daily updates are off. The list that came with the plugin is used.'=>'Les mises à jour quotidiennes sont désactivées. La liste fournie avec le plugin est utilisée.','Checked: %s.'=>'Vérifié : %s.','Model lists refreshed.'=>'Listes de modèles actualisées.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Votre clé IA a été enregistrée par une version plus récente de l\'une de vos extensions. Mettez cette extension à jour ou saisissez à nouveau la clé dans les paramètres de l\'IA.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Votre clé IA enregistrée ne peut plus être ouverte (les clés de sécurité du site ont changé). Saisissez-la à nouveau dans les paramètres de l\'IA.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'L\'IA n\'est pas encore configurée. Ajoutez une clé pour un fournisseur d\'IA dans les paramètres de l\'IA.','No model is chosen for this task. Pick one in the AI settings.'=>'Aucun modèle n\'est sélectionné pour cette tâche. Veuillez en choisir un dans les paramètres de l\'IA.','That AI provider is not supported by this version of the plugin.'=>'Ce fournisseur d\'IA n\'est pas pris en charge par cette version du module d\'extension.','No AI provider that can make images is connected. Add an OpenAI or Google Gemini key in the AI settings.'=>'Aucun fournisseur d\'IA capable de générer des images n\'est connecté. Ajoutez une clé OpenAI ou Google Gemini dans les paramètres de l\'IA.','This AI provider cannot make images. Choose OpenAI or Google Gemini for images in the AI settings.'=>'Ce fournisseur d\'IA ne peut pas créer d\'images. Choisissez OpenAI ou Google Gemini pour les images dans les paramètres de l\'IA.','Your AI key cannot use any image model. Check the key\'s permissions with the provider, or choose another provider for images.'=>'Votre clé IA ne peut pas utiliser de modèle d\'image. Vérifiez les autorisations de la clé auprès du fournisseur ou choisissez un autre fournisseur pour les images.','No connected AI provider can build a search index. Add a Google Gemini, OpenAI, Mistral or OpenRouter key in the AI settings.'=>'Aucun fournisseur d\'IA connecté ne peut créer un index de recherche. Ajoutez une clé Google Gemini, OpenAI, Mistral ou OpenRouter dans les paramètres d\'IA.','Your AI key cannot use any embedding model. Check the key\'s permissions with the provider, or choose another provider for site search.'=>'Votre clé d\'IA ne peut pas utiliser de modèle d\'incorporation. Vérifiez les autorisations de la clé auprès du fournisseur ou choisissez un autre fournisseur pour la recherche sur le site.','This AI provider cannot build a search index. Connect Google Gemini, OpenAI, Mistral or a compatible service for site search.'=>'Ce fournisseur d\'IA ne peut pas créer d\'index de recherche. Connectez Google Gemini, OpenAI, Mistral ou un service compatible pour la recherche sur le site.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ce site n\'a pas pu joindre votre service d\'IA. Vérifiez qu\'il est en cours d\'exécution et que son adresse est accessible depuis votre serveur web (un service situé sur votre propre ordinateur n\'est pas accessible depuis un site hébergé).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ce site n\'a pas pu joindre %s. Consultez leur page de statut ; s\'ils sont en ligne, votre hébergeur bloque peut-être les connexions sortantes ou l\'adresse est incorrecte.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s indique que votre compte n\'a plus de crédit ni de quota. Ajoutez du crédit ou augmentez votre limite dans votre compte chez eux, puis réessayez.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s n\'a pas accepté votre clé. Elle est peut-être mal saisie, révoquée ou expirée. Créez une nouvelle clé et collez-la ici.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s a refusé cette demande pour votre clé. La clé n\'a peut-être pas accès à ce modèle ou à cette fonctionnalité, ou votre compte doit être vérifié.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Le modèle "%1$s" n\'est pas disponible auprès de %2$s pour votre clé. Choisissez un autre modèle dans les paramètres de l\'IA.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Votre forfait %2$s n\'inclut pas le modèle « %1$s ». Choisissez un autre modèle dans les paramètres de l\'IA ou mettez à niveau votre forfait auprès d\'eux.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s limite la vitesse à laquelle votre clé peut envoyer des requêtes. Patientez une minute et réessayez, ou augmentez votre limite de taux auprès de ce service.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s rencontre des problèmes actuellement (panne ou surcharge de leur côté). Vos paramètres ne sont pas en cause. Réessayez dans un moment.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'La requête IA a échoué pour une raison que nous n\'avons pas pu identifier. Réessayez ; si le problème persiste, contactez le support en fournissant les détails ci-dessous.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Le fournisseur d\'IA a répondu sous un format que ce plugin ne peut pas lire. Réessayez ; si le problème persiste, choisissez un autre modèle ou contactez le support.','Custom (OpenAI-compatible)'=>'Personnalisé (compatible OpenAI)','Save a key for this provider first.'=>'Enregistrez d\'abord une clé pour ce fournisseur.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Votre clé fonctionne, mais le fournisseur ne liste aucun modèle de texte pour celle-ci. Ajoutez un modèle vous-même ci-dessous.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Connecté. %1$s a répondu en utilisant %2$s. Vos fonctionnalités d\'IA sont prêtes à être utilisées.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Votre rôle d\'utilisateur n\'est pas autorisé à utiliser l\'IA sur ce site. Veuillez contacter un administrateur.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ce site a atteint sa limite mensuelle de dépenses en IA. Un administrateur peut l\'augmenter dans les paramètres de l\'IA.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ce site a atteint sa limite mensuelle de requêtes IA. Un administrateur peut l\'augmenter dans les paramètres de l\'IA.','Usage and cost'=>'Utilisation et coût','The log, limits and role permissions apply to AI used through: %s.'=>'Le journal, les limites et les autorisations des rôles s\'appliquent à l\'IA utilisée via : %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Les coûts sont approximatifs, calculés à partir des prix publiés ; un modèle sans prix connu est compté comme zéro.','This month: %1$s requests, about %2$s.'=>'Ce mois-ci : %1$s requêtes, soit environ %2$s.','When'=>'Quand','Who'=>'Qui','Used for'=>'Utilisé pour','Model'=>'Modèle','Tokens in / out'=>'Jetons d\'entrée / de sortie','About'=>'À propos','Result'=>'Résultat','No AI requests have been made yet.'=>'Aucune requête d\'IA n\'a encore été effectuée.','Done'=>'Terminé','Limits and permissions'=>'Limites et autorisations','Monthly spending limit (US dollars)'=>'Plafond de dépenses mensuel (en dollars US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Laissez vide pour désactiver la limite. L\'IA s\'arrête pour le reste du mois dès que le coût estimé l\'atteint.','Monthly request limit'=>'Limite de requêtes mensuelles','Leave empty for no limit.'=>'Laissez vide pour ne définir aucune limite.','Who may use AI'=>'Qui peut utiliser l\'IA','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Ne cochez rien pour permettre à toute personne pouvant utiliser les fonctionnalités du plugin d\'utiliser l\'IA. Les administrateurs peuvent toujours l\'utiliser.','Save limits and permissions'=>'Enregistrer les limites et les autorisations','Limits and permissions saved.'=>'Limites et autorisations enregistrées.','Content'=>'Contenu','Not found.'=>'Introuvable.','%s joined the chat.'=>'%s a rejoint le chat.','Type a reply first.'=>'Veuillez d\'abord rédiger une réponse.','The chat has ended. Thank you for contacting us.'=>'La conversation est terminée. Nous vous remercions d\'avoir pris contact avec nous.','You are chatting with the assistant again.'=>'Vous discutez à nouveau avec l\'assistant.','This conversation is now ticket #%d. We will reply by email.'=>'Cette conversation est désormais le ticket #%d. Nous vous répondrons par e-mail.','Type a question first.'=>'Veuillez d\'abord poser une question.','The whole site is being read again in the background.'=>'Le site tout entier est en cours de réanalyse en arrière-plan.','Meanings are being rebuilt in the background.'=>'Les significations sont en cours de reconstruction en arrière-plan.','Submit a ticket form'=>'Soumettre un formulaire de ticket','Heading'=>'Titre','Default subject'=>'Objet par défaut','Button text'=>'Texte du bouton','Show the subject field (yes or no)'=>'Afficher le champ de l\'objet (oui ou non)','My support requests'=>'Mes demandes d\'assistance','Chat button'=>'Boutique de clavardage','Chat with us'=>'Discutez avec nous','Support'=>'Support','Thank you. Your request is ticket #%d. We have emailed you a link to follow it.'=>'Merci. Votre demande porte le numéro de ticket #%d. Nous vous avons envoyé par e-mail un lien pour la suivre.','Your reply has been sent.'=>'Votre réponse a bien été envoyée.','If there is a request under that address, we have emailed you a new link.'=>'Si une demande a été effectuée à cette adresse, nous vous avons envoyé un nouveau lien par e-mail.','Something went wrong. Please check the form and try again.'=>'Un problème est survenu. Veuillez vérifier le formulaire et réessayer.','Your message could not be sent.'=>'Votre message n\'a pas pu être envoyé.','You are sending messages too quickly. Please wait a little and try again.'=>'Vous envoyez des messages trop rapidement. Veuillez patienter un instant et réessayer.','Please agree to the privacy notice to send your request.'=>'Veuillez accepter l\'avis de confidentialité pour envoyer votre demande.','Please complete the check to show you are not a robot.'=>'Veuillez effectuer la vérification pour prouver que vous n\'êtes pas un robot.','Sign in to see your support requests.'=>'Connectez-vous pour consulter vos demandes de support.','Your name'=>'Votre nom','Your email'=>'Votre e-mail','Subject'=>'Objet','Which order is this about?'=>'De quelle commande s\'agit-il ?','Not about an order'=>'Sans rapport avec une commande','How can we help?'=>'Comment pouvons-nous vous aider ?','Privacy policy'=>'Politique de confidentialité','Send request'=>'Envoyer la requête','All requests'=>'Toutes les requêtes','Your support requests'=>'Vos demandes d\'assistance','You have no support requests yet.'=>'Vous n\'avez pas encore de demandes de support.','Updated'=>'Mis à jour','New request'=>'Nouvelle demande','This link has expired. Enter your email address and we will send you a new one.'=>'Ce lien a expiré. Saisissez votre adresse e-mail et nous vous en enverrons un nouveau.','This link is not valid. Enter your email address and we will send you a link to your requests.'=>'Ce lien n\'est pas valide. Entrez votre adresse e-mail et nous vous enverrons un lien vers vos demandes.','Email me a new link'=>'Envoyer-moi un nouveau lien','Request #%1$d: %2$s'=>'Demande n°%1$d : %2$s','Status:'=>'Statut :','Your reply'=>'Votre réponse','Send reply'=>'Envoyer la réponse','You'=>'Vous','Submit a ticket'=>'Soumettre un ticket','Add to Menu'=>'Ajouter au menu','Create the support page on the Zinn® Chat setup screen to add a "Submit a ticket" link.'=>'Créez la page d\'assistance sur l\'écran de configuration de Zinn® Chat pour ajouter un lien « Soumettre un ticket ».','[#%1$d] We have your request: %2$s'=>'[#%1$d] Nous avons bien reçu votre demande : %2$s','Thank you for contacting us. We have received your request and will reply as soon as we can.'=>'Nous vous remercions d\'avoir pris contact avec nous. Nous avons bien reçu votre demande et nous y répondrons dans les plus brefs délais.','View your request'=>'Consulter votre demande','[#%1$d] New ticket: %2$s'=>'[#%1$d] Nouveau ticket : %2$s','Open the ticket'=>'Ouvrir le ticket','[#%1$d] New reply: %2$s'=>'[#%1$d] Nouvelle réponse : %2$s','You can reply on the page below.'=>'Vous pouvez répondre sur la page ci-dessous.','View and reply'=>'Afficher et répondre','[#%1$d] Customer replied: %2$s'=>'[#%1$d] Le client a répondu : %2$s','A visitor is waiting in chat #%d'=>'Un visiteur attend dans le chat #%d','A visitor asked to talk to a person and is waiting for an answer.'=>'Un visiteur a demandé à parler à une personne et attend une réponse.','Answer now'=>'Répondre maintenant','Your chat with %s'=>'Votre discussion avec %s','[#%d] Your link to your request'=>'[#%d] Votre lien vers votre demande','Here is a new link to your request. The old one no longer works.'=>'Voici un nouveau lien pour votre demande. L\'ancien ne fonctionne plus.','From: %s'=>'De : %s','a visitor'=>'un visiteur','Zinn® Chat chats and support tickets'=>'Discussions et tickets de support de Zinn® Chat','Chats'=>'Discussions','Started'=>'Démarré','Name'=>'Nom','Email'=>'E-mail','Page'=>'Page','Messages'=>'Messages','Support tickets'=>'Tickets de support','Ticket'=>'Ticket','Opened'=>'Ouvert','When you use the chat or submit a support request, we store your messages, the name and email address you give us, the page you were on and a coded form of your IP address, so that we can answer you and keep a record of your request.'=>'Lorsque vous utilisez le chat ou soumettez une demande d\'assistance, nous stockons vos messages, le nom et l\'adresse e-mail que vous nous fournissez, la page sur laquelle vous vous trouviez ainsi qu\'une version cryptée de votre adresse IP, afin de pouvoir vous répondre et conserver une trace de votre demande.','If our AI assistant answers you, your message and passages from this website are sent to the AI provider we use to produce the answer.'=>'Si notre assistant virtuel vous répond, votre message et des passages de ce site Web sont envoyés au fournisseur d\'IA que nous utilisons pour générer la réponse.','The chat is not available right now.'=>'Le clavardage n\'est pas disponible pour le moment.','Please type a message.'=>'Veuillez saisir un message.','Please agree to the privacy notice to start the chat.'=>'Veuillez accepter la politique de confidentialité pour démarrer le chat.','You have started too many chats today. Please try again tomorrow or send us a ticket.'=>'Vous avez démarré trop de conversations aujourd\'hui. Veuillez réessayer demain ou nous envoyer un ticket.','The chat could not be started. Please try again.'=>'Le chat n\'a pas pu être démarré. Veuillez réessayer.','Nobody can answer in chat right now. Leave your email address and we will reply by email.'=>'Personne ne peut répondre dans le chat pour le moment. Laissez votre adresse e-mail et nous vous répondrons par e-mail.','The assistant cannot answer right now. You can ask for a person or leave us a message.'=>'L\'assistant ne peut pas répondre pour le moment. Vous pouvez demander à parler à une personne ou nous laisser un message.','We are putting you through to a person. Please stay on this page.'=>'Nous vous mettons en relation avec une personne. Veuillez rester sur cette page.','This chat has ended.'=>'Cette conversation est terminée.','Tickets are not available right now.'=>'Les billets ne sont pas disponibles pour le moment.','Visitor'=>'Visiteur','Team'=>'Équipe','Chat so far:'=>'Historique du chat :','Thank you. Your request is ticket #%d and we will reply by email.'=>'Merci. Votre demande fait l\'objet du ticket n°%d et nous vous répondrons par e-mail.','Please enter a valid email address.'=>'Veuillez saisir une adresse e-mail valide.','This link is not valid.'=>'Ce lien n\'est pas valide.','This link has expired. We can email you a new one.'=>'Ce lien a expiré. Nous pouvons vous en envoyer un nouveau par e-mail.','You cannot see this ticket.'=>'Vous ne pouvez pas voir ce ticket.','Hi! Ask me anything about this site. I answer from its own pages, and I can put you through to a person.'=>'Bonjour ! Posez-moi toutes vos questions sur ce site. Je réponds à partir de ses propres pages et je peux vous mettre en relation avec une personne.','Hi! How can we help? Send us a message and we will get back to you.'=>'Bonjour ! Comment pouvons-nous vous aider ? Envoyez-nous un message et nous vous répondrons dans les plus brefs délais.','Nobody is online right now. Leave your question and email address and we will reply by email.'=>'Personne n\'est en ligne pour le moment. Laissez votre question et votre adresse e-mail et nous vous répondrons par e-mail.','We keep this conversation so we can answer you.'=>'Nous conservons cette conversation afin de pouvoir vous répondre.','Please enter a valid email address so we can reply.'=>'Veuillez entrer une adresse e-mail valide afin que nous puissions vous répondre.','Please describe what you need help with.'=>'Veuillez décrire le sujet pour lequel vous avez besoin d\'aide.','The ticket could not be saved. Please try again.'=>'Le ticket n\'a pas pu être enregistré. Veuillez réessayer.','That ticket does not exist.'=>'Ce ticket n\'existe pas.','The reply is empty.'=>'La réponse est vide.','Waiting for customer'=>'En attente du client','Solved'=>'Résolu','Closed'=>'Fermé','Open chat'=>'Ouvrir le chat','I agree'=>'J\'accepte','Type your message…'=>'Tapez votre message...','Send'=>'Envoyer','Close chat'=>'Fermer le chat','Minimise'=>'Réduire','Talk to a person'=>'Parler à un conseiller','Leave a message'=>'Laisser un message','Your message'=>'Votre message','Send message'=>'Envoyer le message','Cancel'=>'Annuler','Support team'=>'Équipe de support','is typing…'=>'en train d\'écrire…','Looking this up…'=>'Recherche en cours...','Sources'=>'Sources','Was this helpful?'=>'Cela vous a-t-il été utile ?','Yes'=>'Oui','No'=>'Non','Thank you for your feedback.'=>'Nous vous remercions pour vos commentaires.','Email me this chat'=>'Envoyez-moi ce chat par e-mail','Sent.'=>'Envoyé','End chat'=>'Terminer la conversation','The chat has ended.'=>'La discussion est terminée.','Something went wrong. Please try again.'=>'Une erreur s\'est produite. Veuillez réessayer.','Powered by Zinn® Chat'=>'Propulsé par Zinn® Chat','Start a new chat'=>'Démarrer une nouvelle discussion','Get help with this order'=>'Obtenir de l\'aide pour cette commande','Order #%1$s (%2$s)'=>'Commande n° %1$s (%2$s)','%s — guides and services'=>'%s — guides et services','User guides'=>'Guides utilisateur','Read the %s user guide'=>'Lire le guide utilisateur %s','Hide this'=>'Masquer ceci','Zinn® hosting for WordPress'=>'Hébergement Zinn® pour WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, sauvegardes quotidiennes, migration gratuite et panneau de contrôle conçu pour ceux qui gèrent plusieurs sites.','The Zinn® marketplace'=>'Le marché Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Achetez et vendez des sites établis, des noms de domaine et des emplacements de liens, les fonds étant conservés en toute sécurité jusqu\'à ce que les deux parties soient satisfaites.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — engagez des professionnels pour faire ce travail','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Notre place de marché mondiale de freelances : parcourez plus de 10 000 services prêts à l\'emploi proposés par des rédacteurs, designers, développeurs et experts en SEO, ou publiez un projet et laissez-les faire des offres.','See the Zinn Digital® release notes.'=>'Consultez les notes de version de Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Le service de mise à jour Zinn® n\'a pas généré de lien de téléchargement pour cette mise à jour. Vérifiez que ce site peut accéder à la plateforme Zinn®, puis réessayez.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'La mise à jour n\'a pas pu être téléchargée depuis le service de mise à jour Zinn® (%s). Réessayez dans quelques minutes.','The downloaded update failed its integrity check and was not installed.'=>'La mise à jour téléchargée a échoué au contrôle d\'intégrité et n\'a pas été installée.','Part of the message telling the user what they should receive via email.a license key'=>'une clé de licence','A user has not yet been associated with the license, which is necessary to prevent unauthorized activation. To assign the license to your user, you agree to share your WordPress user\'s full name and email address.'=>'Aucun utilisateur n\'a encore été associé à la licence, ce qui est nécessaire pour empêcher toute activation non autorisée. Pour attribuer la licence à votre utilisateur, vous acceptez de partager le nom complet et l\'adresse e-mail de votre utilisateur WordPress.','the above-mentioned sites'=>'les sites susmentionnés','Account'=>'Compte','Account Details'=>'Détails du compte','Account is pending activation. Please check your email and click the link to activate your account and then submit the affiliate form again.'=>'Le compte est en attente d\'activation. Veuillez consulter votre e-mail et cliquer sur le lien pour activer votre compte, puis soumettez à nouveau le formulaire d\'affilié.','Would you like to merge %1$s into %2$s?'=>'Souhaitez-vous fusionner %1$s dans %2$s ?','Actions'=>'Actions','Activate'=>'Activer','Activate Free Version'=>'Activer la version gratuite','Activate License'=>'Activer la licence','activate a license here'=>'activer une licence ici','Please enter the license key that you received in the email right after the purchase:'=>'Veuillez entrer la clé de licence que vous avez reçue dans l\'e-mail juste après l\'achat :','Activate license on all sites in the network.'=>'Activer la licence sur tous les sites du réseau.','Activate license on all pending sites.'=>'Activer la licence sur tous les sites en attente.',' The paid version of %1$s is already installed. Please activate it to start benefiting from the %2$s features. %3$s'=>'La version payante de %1$s est déjà installée. Veuillez l\'activer pour commencer à profiter des fonctionnalités de %2$s. %3$s',' The paid version of %1$s is already installed. Please navigate to the %2$s to activate it and start benefiting from the %3$s features.'=>'La version payante de %1$s est déjà installée. Veuillez vous rendre dans %2$s pour l\'activer et commencer à profiter des fonctionnalités de %3$s.','Activate this add-on'=>'Activer ce modu